import type { ContinutLectie } from "./tipuri";
import { continutVectoriInPlan } from "./lectii/m5-vectori-in-plan";

export type CriteriiCautareContinut = {
  slug: string;
  modul?: number;
  numarLectie?: number;
};

export type RezultatContentEngine = {
  continut: ContinutLectie | null;
  gasit: boolean;
  publicabil: boolean;
};

const registruContinut: ContinutLectie[] = [
  continutVectoriInPlan,
];

function estePublicabil(
  continut: ContinutLectie
): boolean {
  const verificare = continut.verificare;

  return (
    verificare.status === "publicabil" &&
    verificare.verificatMatematic === true &&
    verificare.verificatPrograma === true &&
    verificare.verificatExercitii === true &&
    verificare.verificatLimbaRomana === true
  );
}

export function obtineContinutLectie(
  criterii: CriteriiCautareContinut
): RezultatContentEngine {
  const continut =
    registruContinut.find((lectie) => {
      const acelasiSlug = lectie.slug === criterii.slug;

      const acelasiModul =
        criterii.modul === undefined ||
        lectie.modul === criterii.modul;

      const acelasiNumar =
        criterii.numarLectie === undefined ||
        lectie.numarLectie === criterii.numarLectie;

      return acelasiSlug && acelasiModul && acelasiNumar;
    }) ?? null;

  if (!continut) {
    return {
      continut: null,
      gasit: false,
      publicabil: false,
    };
  }

  return {
    continut,
    gasit: true,
    publicabil: estePublicabil(continut),
  };
}